-- Answer keys + explanations (private).
insert into private.quiz_answer_keys (quiz_id, question_id, correct_option, option_count, explanation) values
  ('l0-plagiarism-quiz', 1, 2, 4, 'The wording and ideas come from someone else without credit. Changing a few words does not make them yours.'),
  ('l0-plagiarism-quiz', 2, 1, 4, 'AI-written work submitted as your own, with no disclosure, breaks the ownership and disclosure rules.'),
  ('l0-plagiarism-quiz', 3, 3, 4, 'Kiran presents another person''s structure and findings as his own, and sharing a finished file made the copying easy.'),
  ('l0-plagiarism-quiz', 4, 0, 4, 'Quotation marks, a named source and your own analysis are the correct way to use someone else''s work.'),
  ('l0-plagiarism-quiz', 5, 2, 4, 'AI helped with brainstorming, the research and thinking were his own, and he disclosed the AI use.'),
  ('l0-plagiarism-quiz', 6, 1, 4, 'Reusing an earlier submission as new work needs permission.'),
  ('l0-plagiarism-quiz', 7, 3, 4, 'Work you cannot explain cannot be defended, and the learning the module was meant to give has not happened.'),
  ('l0-plagiarism-quiz', 8, 0, 4, 'AI can invent sources. Open and check every reference before you use it.'),
  ('l0-plagiarism-quiz', 9, 2, 4, 'Someone else did the work and he claimed it, which is cheating as well as plagiarism.'),
  ('l0-plagiarism-quiz', 10, 1, 4, 'Early shortcuts leave skill gaps that the capstone and the jury expose, and the certificate then says little about real ability.')
on conflict (quiz_id, question_id) do update
