-- Questions + options (readable by registered students; no answers).
insert into public.quiz_questions (quiz_id, question_id, position, prompt, options) values
  ('l0-plagiarism-quiz', 1, 1, 'Meera is short of time for her Module 2 document. She copies three paragraphs from a blog post, changes a few words, and does not mention the blog. What is this?',
   '["Fine, because she changed some words.","Fine, because blogs are public.","Plagiarism, because the ideas and wording come from someone else without credit.","Plagiarism only if the blog''s author finds out."]'::jsonb),
  ('l0-plagiarism-quiz', 2, 2, 'Arjun asks an AI tool to write his whole assignment on user personas, pastes the result into his document and submits it with no note. What has he done?',
   '["Nothing wrong, since an AI tool is not a person.","He submitted AI-written work as his own and did not disclose the AI use.","He broke a rule only if the text has errors.","Nothing wrong, because he formatted the document himself."]'::jsonb),
  ('l0-plagiarism-quiz', 3, 3, 'Kiran''s friend Sana, who has finished the assignment, sends him her file "just for reference". Kiran keeps her structure and findings and changes the wording. What is the best description?',
   '["Acceptable, because Sana agreed to share it.","Acceptable if he changes at least half the words.","Not a problem for Kiran, because Sana shared it first.","Plagiarism: Kiran presents Sana''s structure and findings as his own, and sharing a finished file made it possible."]'::jsonb),
  ('l0-plagiarism-quiz', 4, 4, 'Nisha reads a research article and quotes two lines in quotation marks, with the author''s name and a link. She then adds her own analysis. Is this plagiarism?',
   '["No, because she quoted, credited the source and added her own thinking.","Yes, because she used someone else''s words.","Yes, unless she gets the author''s permission.","No, but only because the quote is short."]'::jsonb),
  ('l0-plagiarism-quiz', 5, 5, 'Rohit uses an AI tool to suggest interview questions for his user research. He edits them for his users, runs real interviews, writes his own findings and adds an AI use note. How does this fit the ground rules?',
   '["It is not allowed, because any use of AI is banned.","It is not allowed, because AI cannot help with research.","It is allowed: AI helped with brainstorming, he did the real research and the thinking, and he disclosed it.","It is allowed, but only if he does not mention AI."]'::jsonb),
  ('l0-plagiarism-quiz', 6, 6, 'Tanvi wants to reuse most of her Module 1 document for her Module 3 assignment to save time. She does not tell anyone. What is this?',
   '["Fine, because it is her own work.","Self-plagiarism: reusing an earlier submission as new work without permission.","Fine, if she changes the title.","Not a problem, because the modules are different."]'::jsonb),
  ('l0-plagiarism-quiz', 7, 7, 'For her jury presentation, Divya has an AI tool write the script and the slides. The jury asks why she chose her target users, and she cannot answer. What is the main problem?',
   '["The slides were too long.","The jury asked an unfair question.","AI scripts are always wrong.","She presented work she did not understand, so she could not defend it and did not build the skill the module is meant to teach."]'::jsonb),
  ('l0-plagiarism-quiz', 8, 8, 'An AI tool gives Vikram three references for his market-size estimate. He adds them to his document without opening them, and one of them does not exist. What went wrong?',
   '["He did not verify the AI''s output, and he presented an invented source as real.","Nothing, because the AI supplied them.","Only the AI tool is responsible.","He should have listed fewer references."]'::jsonb),
  ('l0-plagiarism-quiz', 9, 9, 'Ishaan is busy and pays a senior to write his assignment document. He submits it under his own name. Which statement is correct?',
   '["It is fine, because he paid for the work.","It is fine, if the senior writes well.","It is plagiarism and cheating: someone else did the work and he claimed it as his own.","It is fine, as long as he presents it to the jury himself."]'::jsonb),
  ('l0-plagiarism-quiz', 10, 10, 'A learner copies the assignments for the first four modules. When the capstone project and the jury presentations arrive, they need the skills those modules were meant to build. What is the most likely result?',
   '["Nothing, because the earlier modules are not connected to the capstone.","The learner struggles to apply the skills, the work is hard to defend, and the certificate and portfolio do not reflect real ability.","The jury lowers its standards for that learner.","The learner does better, because copying shows good examples."]'::jsonb)
on conflict (quiz_id, question_id) do update
  set position = excluded.position,
      prompt   = excluded.prompt,
      options  = excluded.options;

-- Subtopics (structured, verbatim content).
insert into public.course_subtopics
  (id, level_id, topic_number, topic_title, position, title, summary, reading_minutes, body,
   acknowledgment_text, quiz_id, source_document_path, source_document_name, source_document_sha256)
values
  ('l0-program-introduction', 1, 1, 'Welcome to the Program', 1, 'Program introduction',
   'Product Wizardry adds product thinking to the technical skills you already have, so you learn to build the right thing and not just to build things right.', 4,
   '[{"type":"paragraph","runs":[{"t":"Product Wizardry adds product thinking to the technical skills you already have, so you learn to build the right thing and not just to build things right. Reading time: about 4 minutes."}]},{"type":"paragraph","runs":[{"t":"Welcome.","b":true},{"t":" Product Wizardry is a hands-on program for tech undergraduate students, taught in person in a classroom. Over 12 modules you will learn how products are discovered, defined, built and measured, and you will practise on real assignments that you present to a jury."}]},{"type":"heading","level":3,"text":"Why developers need product acumen"},{"type":"list","ordered":false,"items":[[{"t":"Code answers \"how\"; product answers \"what and why\".","b":true},{"t":" A developer who understands users makes better choices in every task: what to build first, what to cut, what to test."}],[{"t":"It avoids wasted work.","b":true},{"t":" A common reason products fail is that they solve a problem nobody has, not that the code was poor."}],[{"t":"It earns trust and ownership.","b":true},{"t":" Teams give more responsibility to engineers who can talk to users and explain trade-offs."}],[{"t":"It improves teamwork.","b":true},{"t":" You can speak the same language as product managers, designers and business teams."}]]},{"type":"heading","level":3,"text":"Jobs that reward this skill"},{"type":"paragraph","runs":[{"t":"Titles differ between companies. These are common examples of roles where product and technical skills meet."}]},{"type":"table","header":[[{"t":"Role"}],[{"t":"What you do"}]],"rows":[[[{"t":"Product engineer"}],[{"t":"Build features end to end and help decide what to build"}]],[[{"t":"Technical product manager"}],[{"t":"Own a platform, API or developer tool, working closely with engineers"}]],[[{"t":"Associate product manager"}],[{"t":"Manage a product area; many product managers begin as engineers"}]],[[{"t":"Founding engineer at a startup"}],[{"t":"Build the product with a small team and make product calls daily"}]],[[{"t":"Solutions or forward-deployed engineer"}],[{"t":"Work with customers to fit the product to their needs"}]],[[{"t":"AI product engineer"}],[{"t":"Build AI-enabled features and check that they work for users"}]]]},{"type":"paragraph","runs":[{"t":"Companies that hire for these roles.","b":true},{"t":" Product-led companies of all sizes hire for the roles above. These are examples, so look at each company''s careers page for current openings."}]},{"type":"list","ordered":false,"items":[[{"t":"In India:","b":true},{"t":" Flipkart, Swiggy, Zomato, Razorpay, PhonePe, CRED, Meesho, Zerodha, Freshworks and Zoho, plus the India teams of global firms such as Google, Microsoft, Amazon, Atlassian and Adobe."}],[{"t":"Abroad:","b":true},{"t":" Google, Microsoft, Amazon, Meta, Apple, Atlassian, Stripe, Shopify, Spotify, Uber and Airbnb, along with AI-focused companies and startups."}]]},{"type":"paragraph","runs":[{"t":"The list comes from general industry knowledge, not a study, and it is not a promise of hiring or an endorsement of any company."}]},{"type":"heading","level":3,"text":"How AI has changed the demand for these roles"},{"type":"list","ordered":false,"items":[[{"t":"AI tools now write a large share of routine code, so typing code is less of the bottleneck."}],[{"t":"What remains scarce is judgement: deciding what to build, checking that the result is right, and understanding users."}],[{"t":"Techies who can direct AI tools "},{"t":"and","b":true},{"t":" think like a product person are well placed. This is a direction, not a guarantee of a job."}]]},{"type":"heading","level":3,"text":"How it helps with entrepreneurship"},{"type":"list","ordered":false,"items":[[{"t":"A product-minded developer can take an idea from problem to working prototype alone, using AI tools to move fast."}],[{"t":"You learn to test whether people want an idea "},{"t":"before","b":true},{"t":" building it, through interviews, simple prototypes and small experiments."}],[{"t":"Many startups begin with one person who can both build and decide. This program gives you those habits: start with the problem, collect evidence, take small steps."}]]},{"type":"paragraph","runs":[{"t":"This program will not make you a founder on its own. It gives you the tools to test an idea cheaply and decide whether to continue."}]},{"type":"heading","level":3,"text":"How it builds a foundation for forward-deployed engineer (FDE) roles"},{"type":"paragraph","runs":[{"t":"A forward-deployed engineer works closely with customers, understands their problem, and builds or adapts the product to solve it. The title became well known through Palantir and is now used by many enterprise software and AI companies."}]},{"type":"list","ordered":false,"items":[[{"t":"Start from the customer''s problem.","b":true},{"t":" The program trains you to understand the user''s need before you write any code, which is the first step of an FDE''s work."}],[{"t":"Make decisions and trade-offs.","b":true},{"t":" You practise choosing what to build and what to leave out, with limited time."}],[{"t":"Communicate with non-technical people.","b":true},{"t":" Your documents and jury presentations are practice for explaining technical work to customers and business teams."}],[{"t":"Own the outcome.","b":true},{"t":" Each assignment asks you to take work from idea to a finished document and presentation, which builds the ownership FDE roles expect."}],[{"t":"Work with AI tools.","b":true},{"t":" You learn to use AI tools to build and move quickly while checking what they produce."}]]},{"type":"paragraph","runs":[{"t":"FDE roles usually also ask for strong engineering skills, so keep building your technical skills alongside this program. Think of Product Wizardry as the foundation that makes your engineering more useful to customers."}]}]'::jsonb,
   'I have read and understood the Program introduction.', null, 'level-0/module-0-welcome-to-the-program.docx', 'Product Wizardry (Offline)_Module 0_Welcome to the Program.docx', '29f2bd4132d1c56b73482059cd8533e0582add9aa24f1d6a1b9da2d305ddd63b')
on conflict (id) do update
  set level_id = excluded.level_id, topic_number = excluded.topic_number, topic_title = excluded.topic_title,
      position = excluded.position, title = excluded.title, summary = excluded.summary,
