insert into public.course_subtopics
  (id, level_id, topic_number, topic_title, position, title, summary, reading_minutes, body,
   acknowledgment_text, quiz_id, source_document_path, source_document_name, source_document_sha256)
values
  ('l0-program-outline', 1, 1, 'Welcome to the Program', 2, 'Program outline',
   'The program has 12 modules, numbered 0 to 11, taught through live classroom lectures, and every module follows the same pattern: learn, check, then apply.', 3,
   '[{"type":"paragraph","runs":[{"t":"The program has 12 modules, numbered 0 to 11, taught through live classroom lectures, and every module follows the same pattern: learn, check, then apply. Reading time: about 3 minutes."}]},{"type":"paragraph","runs":[{"t":"You are in Module 0, which sets expectations before you start. It has two topics, and you are reading the first one, "},{"t":"Welcome to the Program","b":true},{"t":"."}]},{"type":"paragraph","runs":[{"t":"Duration and pace.","b":true},{"t":" The program takes about "},{"t":"6 months","b":true},{"t":" to complete, at a pace of "},{"t":"two modules per month","b":true},{"t":"."}]},{"type":"heading","level":3,"text":"How each module is built"},{"type":"table","header":[[{"t":"Level"}],[{"t":"What it contains"}]],"rows":[[[{"t":"Module"}],[{"t":"A set of topics, plus one assignment"}]],[[{"t":"Topic"}],[{"t":"A set of subtopics, plus MCQs to check your understanding"}]],[[{"t":"Subtopic"}],[{"t":"A live classroom lecture, reading material and links for further reading"}]]]},{"type":"heading","level":3,"text":"What you do in each module"},{"type":"list","ordered":true,"items":[[{"t":"Attend the live classroom lectures."}],[{"t":"Read the material for each subtopic and follow the links."}],[{"t":"Attempt the MCQs at the end of each topic."}],[{"t":"Complete the module assignment."}]]},{"type":"paragraph","runs":[{"t":"Live lectures happen at a scheduled time, so plan to be in the classroom. Your program team will share the timetable."}]},{"type":"heading","level":3,"text":"The assignment"},{"type":"paragraph","runs":[{"t":"Every module has one assignment, and each assignment has "},{"t":"two parts","b":true},{"t":":"}]},{"type":"list","ordered":false,"items":[[{"t":"Document submission:","b":true},{"t":" you write and submit a document on the module''s work."}],[{"t":"Presentation to the jury:","b":true},{"t":" you present your work to a jury and answer their questions."}]]},{"type":"heading","level":3,"text":"Guest lectures"},{"type":"paragraph","runs":[{"t":"From time to time, product pioneers from the industry will give guest lectures to add more value to your practical learning. You will be informed about each lecture as it is scheduled, and most of them will be held over the weekends."}]},{"type":"paragraph","runs":[{"t":"The next section explains how assignments, content and the capstone project count towards your final score."}]}]'::jsonb,
   'I have read and understood the Program outline.', null, 'level-0/module-0-welcome-to-the-program.docx', 'Product Wizardry (Offline)_Module 0_Welcome to the Program.docx', '29f2bd4132d1c56b73482059cd8533e0582add9aa24f1d6a1b9da2d305ddd63b')
