insert into public.course_subtopics
  (id, level_id, topic_number, topic_title, position, title, summary, reading_minutes, body,
   acknowledgment_text, quiz_id, source_document_path, source_document_name, source_document_sha256)
values
  ('l0-completion-requirements', 1, 1, 'Welcome to the Program', 3, 'Completion requirements',
   'To earn the certificate, you need more than 70% in your required individual assignments and in the capstone project, and your final score is built from three parts.', 3,
   '[{"type":"paragraph","runs":[{"t":"To earn the certificate, you need more than 70% in your required individual assignments and in the capstone project, and your final score is built from three parts. Reading time: about 3 minutes."}]},{"type":"heading","level":3,"text":"1. Pass mark for assignments"},{"type":"list","ordered":false,"items":[[{"t":"Score "},{"t":"more than 70%","b":true},{"t":" in the required individual assignments."}],[{"t":"Score "},{"t":"more than 70%","b":true},{"t":" in the capstone project."}],[{"t":"\"More than 70%\" means above 70, so exactly 70% is not enough."}]]},{"type":"heading","level":3,"text":"2. Content completion"},{"type":"paragraph","runs":[{"t":"To meet the content completion requirement, you need a minimum of "},{"t":"80%","b":true},{"t":" in each of the following:"}]},{"type":"list","ordered":false,"items":[[{"t":"Attendance:","b":true},{"t":" at least 80% of the live classroom lectures attended."}],[{"t":"MCQs:","b":true},{"t":" at least 80% of the MCQs completed on the LMS."}]]},{"type":"paragraph","runs":[{"t":"Content completion carries 20% of your final score. If you miss a lecture, speak to your program team about how to make it up."}]},{"type":"heading","level":3,"text":"3. Final score"},{"type":"paragraph","runs":[{"t":"Your final score combines three parts:"}]},{"type":"table","header":[[{"t":"Component"}],[{"t":"Weightage"}]],"rows":[[[{"t":"Individual assignments"}],[{"t":"50%"}]],[[{"t":"Capstone project"}],[{"t":"30%"}]],[[{"t":"Content completion"}],[{"t":"20%"}]],[[{"t":"Total","b":true}],[{"t":"100%","b":true}]]],"emphasizeLastRow":true},{"type":"formula","text":"Final score = 0.5 x Assignments + 0.3 X Capstone + 0.2 x Completion"},{"type":"paragraph","runs":[{"t":"Example:","b":true},{"t":" If your assignments score 80%, your capstone scores 75% and your content completion is 100%, your final score is 0.5 × 80 + 0.3 × 75 + 0.2 × 100 = 40 + 22.5 + 20 = "},{"t":"82.5%","b":true},{"t":"."}]},{"type":"heading","level":3,"text":"Certificate"},{"type":"paragraph","runs":[{"t":"You will receive a certificate when you complete the program successfully, by meeting the requirements above."}]},{"type":"heading","level":3,"text":"How the certificate helps your profile"},{"type":"paragraph","runs":[{"t":"The certificate is a signal, and the work behind it is the proof. Employers and founders look at what you can show, so use both."}]},{"type":"list","ordered":false,"items":[[{"t":"A clear signal.","b":true},{"t":" It shows product skills on top of your technical ones, which helps you stand out from profiles that list only languages and tools."}],[{"t":"A portfolio, not just a badge.","b":true},{"t":" Your module documents and capstone project are work samples you can describe in applications."}],[{"t":"Interview-ready communication.","b":true},{"t":" Presenting to a jury and answering questions, module after module, is practice for real interviews."}],[{"t":"Industry exposure.","b":true},{"t":" Guest lectures by product pioneers give you ideas, vocabulary and a sense of how real teams work."}],[{"t":"A story for product and startup roles.","b":true},{"t":" You can explain a problem you framed, the evidence you gathered and the decisions you made, which is what product-minded interviews ask about."}]]},{"type":"paragraph","runs":[{"t":"How to use it","b":true}]},{"type":"list","ordered":true,"items":[[{"t":"Add the certificate to the \"Licenses and certifications\" section of your LinkedIn profile and to your resume."}],[{"t":"Write two or three lines about your capstone project: the problem, what you built or proposed, and the result."}],[{"t":"Share your best documents or presentation where the program allows it."}],[{"t":"Be ready to talk through one real decision you made during the program."}]]},{"type":"paragraph","runs":[{"t":"A certificate does not guarantee an interview or a job. The strongest profiles combine it with work they can show and a clear explanation of it."}]}]'::jsonb,
   'I have read and understood the Completion requirements.', null, 'level-0/module-0-welcome-to-the-program.docx', 'Product Wizardry (Offline)_Module 0_Welcome to the Program.docx', '29f2bd4132d1c56b73482059cd8533e0582add9aa24f1d6a1b9da2d305ddd63b')
