values
  ('l0-faqs', 1, 1, 'Welcome to the Program', 4, 'FAQs',
   'These answers cover the questions learners ask most, based on the program rules in this topic. Where a detail has not been fixed yet, the answer says to ask your program team.', 4,
   '[{"type":"paragraph","runs":[{"t":"These answers cover the questions learners ask most, based on the program rules in this topic. Where a detail has not been fixed yet, the answer says to ask your program team. Reading time: about 4 minutes."}]},{"type":"heading","level":3,"text":"About the program"},{"type":"paragraph","runs":[{"t":"Who is this program for?","b":true},{"t":" Tech undergraduate students and developers who want to add product skills to their technical skills. You do not need to have worked as a product manager."}]},{"type":"paragraph","runs":[{"t":"How many modules are there?","b":true},{"t":" 12 modules, numbered 0 to 11. Module 0, which you are reading now, sets expectations."}]},{"type":"paragraph","runs":[{"t":"How long does the program take?","b":true},{"t":" About 6 months, at two modules per month."}]},{"type":"paragraph","runs":[{"t":"What does each module contain?","b":true},{"t":" Topics and subtopics, each with a live classroom lecture, reading material and links, MCQs at the end of each topic, and one assignment."}]},{"type":"paragraph","runs":[{"t":"Will there be guest lectures?","b":true},{"t":" Yes. Occasionally, product pioneers from the industry will give guest lectures to add practical learning. You will be informed from time to time, and most will be held over the weekends."}]},{"type":"paragraph","runs":[{"t":"Do guest lectures count towards my score?","b":true},{"t":" The completion requirements in section 3 do not include guest lectures. Ask your program team if there is any attendance expectation."}]},{"type":"heading","level":3,"text":"Classes and progress"},{"type":"paragraph","runs":[{"t":"Where and when are the classes held?","b":true},{"t":" Your program team will share the venue and the timetable."}]},{"type":"paragraph","runs":[{"t":"How is content completion measured?","b":true},{"t":" You need at least 80% attendance at the live classroom lectures and at least 80% of the MCQs completed on the LMS."}]},{"type":"paragraph","runs":[{"t":"What if I miss a live lecture?","b":true},{"t":" You can miss some lectures, because the minimum is 80% attendance. Speak to your program team as soon as you can about how to make up what you missed. This document does not fix a make-up rule."}]},{"type":"paragraph","runs":[{"t":"Will the lectures be recorded?","b":true},{"t":" This has not been fixed in this document. Ask your program team."}]},{"type":"paragraph","runs":[{"t":"Do I have to score a pass mark in the MCQs?","b":true},{"t":" This document sets no pass mark for the MCQs. You need to complete at least 80% of them on the LMS. The 70% pass rule applies to the individual assignments and the capstone project."}]},{"type":"paragraph","runs":[{"t":"Can I skip lectures or MCQs?","b":true},{"t":" Content completion needs at least 80% attendance and at least 80% of the MCQs completed on the LMS, and it carries 20% of your final score. Falling below either level means you have not met the requirement."}]},{"type":"heading","level":3,"text":"Assignments and the capstone"},{"type":"paragraph","runs":[{"t":"What is in an assignment?","b":true},{"t":" Two parts: a document submission and a presentation to the jury."}]},{"type":"paragraph","runs":[{"t":"Are all assignments required?","b":true},{"t":" The pass rule applies to the "},{"t":"required","i":true},{"t":" individual assignments. Your program team will tell you which ones those are."}]},{"type":"paragraph","runs":[{"t":"Who is on the jury, and when do presentations happen?","b":true},{"t":" Your program team will share the jury details and the schedule."}]},{"type":"paragraph","runs":[{"t":"Can I resubmit an assignment or retake a presentation?","b":true},{"t":" This has not been fixed in this document. Ask your program team before a deadline."}]},{"type":"paragraph","runs":[{"t":"Can I use AI tools?","b":true},{"t":" Follow the instructions given with each assignment. Whatever tools you use, the work you submit must be your own, and you should be able to explain it to the jury."}]},{"type":"heading","level":3,"text":"Scores and certificate"},{"type":"paragraph","runs":[{"t":"What score do I need?","b":true},{"t":" More than 70% in each required individual assignment and in the capstone project."}]},{"type":"paragraph","runs":[{"t":"I scored exactly 70%. Is that enough?","b":true},{"t":" No. The requirement is "},{"t":"more than","i":true},{"t":" 70%."}]},{"type":"paragraph","runs":[{"t":"How is the final score calculated?","b":true},{"t":" Individual assignments 50%, capstone project 30%, content completion 20%."}]},{"type":"paragraph","runs":[{"t":"What if I score below 70% in an assignment or the capstone?","b":true},{"t":" Then you have not yet met the completion requirement. Ask your program team whether and when you can try again."}]},{"type":"paragraph","runs":[{"t":"Will I get a certificate?","b":true},{"t":" Yes, when you complete the program successfully by meeting the requirements in section 3."}]},{"type":"heading","level":3,"text":"What to do next"},{"type":"paragraph","runs":[{"t":"What happens after I confirm that I have read a section?","b":true},{"t":" Tick the confirmation at the end of the section and move on to the next one. When all four are confirmed, continue to the second topic of Module 0."}]},{"type":"paragraph","runs":[{"t":"Who do I ask if something is unclear?","b":true},{"t":" Your program team."}]}]'::jsonb,
   'I have read and understood the FAQs.', null, 'level-0/module-0-welcome-to-the-program.docx', 'Product Wizardry (Offline)_Module 0_Welcome to the Program.docx', '29f2bd4132d1c56b73482059cd8533e0582add9aa24f1d6a1b9da2d305ddd63b')
