insert into public.course_subtopics
  (id, level_id, topic_number, topic_title, position, title, summary, reading_minutes, body,
   acknowledgment_text, quiz_id, source_document_path, source_document_name, source_document_sha256)
values
  ('l0-plagiarism', 1, 2, 'Ground Rules & Setup', 5, 'Plagiarism',
   'Plagiarism means presenting someone else''s words, ideas, work or AI output as your own, and in this program it costs you the very skills the certificate stands for.', 5,
   '[{"type":"paragraph","runs":[{"t":"Plagiarism means presenting someone else''s words, ideas, work or AI output as your own, and in this program it costs you the very skills the certificate stands for. Reading time: about 5 minutes"}]},{"type":"heading","level":3,"text":"What counts as plagiarism"},{"type":"list","ordered":false,"items":[[{"t":"Copying text, code, designs or data from a website, book, classmate or AI tool and submitting it as your own."}],[{"t":"Changing a few words of someone else''s work without saying where it came from."}],[{"t":"Submitting work that someone else did for you, whether paid or free."}],[{"t":"Reusing your own earlier submission as new work without permission (self-plagiarism)."}],[{"t":"Inventing sources, quotes, interviews or data (fabrication)."}]]},{"type":"heading","level":3,"text":"What is not plagiarism"},{"type":"list","ordered":false,"items":[[{"t":"Quoting someone, with quotation marks and the source."}],[{"t":"Explaining an idea in your own words and crediting where it came from."}],[{"t":"Discussing ideas with classmates, then writing your own work separately."}],[{"t":"Using AI in the ways allowed below, and saying that you did."}]]},{"type":"heading","level":3,"text":"Why it matters here"},{"type":"list","ordered":false,"items":[[{"t":"Learning quality.","b":true},{"t":" Product skills come from doing: framing a problem, talking to users, making trade-offs. Copying skips the practice, so the skill never forms."}],[{"t":"Later modules.","b":true},{"t":" Each module builds on the one before, and the capstone builds on all of them. A gap from an early shortcut shows up later, when it is harder to fix."}],[{"t":"The jury.","b":true},{"t":" You present your work and answer questions. Work you did not do cannot be defended."}],[{"t":"Your outcomes.","b":true},{"t":" The certificate, your portfolio and your interview stories are worth only as much as the skill behind them."}],[{"t":"Fairness and trust.","b":true},{"t":" Classmates who did their own work are compared with you. Product teams also run on trust, and invented data leads to wrong decisions."}]]},{"type":"heading","level":3,"text":"Ground rules for using AI in assignments"},{"type":"paragraph","runs":[{"t":"AI is part of how products are built today, and this program expects you to learn to use it well. These rules keep the work yours."}]},{"type":"list","ordered":true,"items":[[{"t":"You own your work.","b":true},{"t":" You must understand every part of what you submit and be able to explain it to the jury without help."}],[{"t":"Allowed, with disclosure.","b":true},{"t":" Brainstorming ideas, explaining a concept, suggesting an outline, giving feedback on your own draft, checking grammar and clarity, helping to debug code, creating practice questions, and finding counter-arguments."}],[{"t":"Not allowed.","b":true},{"t":" Submitting AI-written text, analysis or designs as your own; having AI do the whole assignment; using AI to answer the jury''s questions; and inventing interviews, survey responses, quotes or data."}],[{"t":"Disclose your use.","b":true},{"t":" Add a short "},{"t":"AI use note","b":true},{"t":" at the end of every document: which tool you used, what for, and what you changed or checked."}],[{"t":"Verify everything.","b":true},{"t":" Check every fact, number, link and citation. AI can invent sources that look real."}],[{"t":"Keep research real.","b":true},{"t":" User interviews, surveys and observations must come from real people you spoke to."}],[{"t":"Protect data.","b":true},{"t":" Do not paste names, phone numbers or confidential information about classmates, users or partners into AI tools."}],[{"t":"If in doubt, ask first.","b":true},{"t":" Check with your program team before you submit, not after."}],[{"t":"Action on breaches.","b":true},{"t":" The program team decides what action to take if these rules are broken."}]]},{"type":"heading","level":3,"text":"A quick check before you submit"},{"type":"list","ordered":true,"items":[[{"t":"Can I explain every part without looking at it?"}],[{"t":"Is every idea, quote and number that came from someone else credited?"}],[{"t":"Have I written down where AI helped?"}]]},{"type":"paragraph","runs":[{"t":"Next, test your understanding with 10 scenario questions."}]},{"type":"quiz","quiz_id":"l0-plagiarism-quiz","heading":"Check your understanding: 10 scenario questions","intro":"Read each scenario and pick the best answer before you look at the answer key. The names and situations are invented for practice.","review_intro":"Check your answers only after you have tried all 10 questions.","post_submission_note":"If you got 8 or more right, you are ready for the assignments. If you got fewer, re-read the ground rules above before you start Module 1."}]'::jsonb,
   'I have read and understood the Plagiarism section and the AI ground rules, and I agree to follow them.', 'l0-plagiarism-quiz', 'level-0/module-0-ground-rules-and-setup.docx', 'Product Wizardry_Module 0_Ground Rules & Setup.docx', 'b739d207425c5319e60e27d866a9a6187e8f7236f8b56b4f517ca817a4e618e4')
