values
  ('l0-system-requirements', 1, 2, 'Ground Rules & Setup', 6, 'System requirements and tools',
   'You need a laptop or desktop that is less than a few years old, a current browser and a stable internet connection of at least 5 Mbps to use the LMS comfortably.', 4,
   '[{"type":"paragraph","runs":[{"t":"You need a laptop or desktop that is less than a few years old, a current browser and a stable internet connection of at least 5 Mbps to use the LMS comfortably. Reading time: about 4 minutes."}]},{"type":"heading","level":3,"text":"Minimum requirements"},{"type":"paragraph","runs":[{"t":"These are minimums for a web-based LMS used from India. The Sources note says which figures come from published pages and which are the program''s own recommendations."}]},{"type":"table","header":[[{"t":"Item"}],[{"t":"Minimum"}],[{"t":"Recommended"}]],"rows":[[[{"t":"Device"}],[{"t":"Laptop or desktop. A phone or tablet can help with reading and MCQs, but not with documents and presentations"}],[{"t":"Laptop with a keyboard and a mouse"}]],[[{"t":"Operating system"}],[{"t":"Windows 10 or later, macOS 13 (Ventura) or later, or a current 64-bit Linux. Android 10 or later on a phone"}],[{"t":"The latest version your device supports"}]],[[{"t":"Browser"}],[{"t":"A current version of Chrome. Keep it updated, and leave JavaScript and cookies switched on"}],[{"t":"Chrome, updated every month"}]],[[{"t":"Processor and memory"}],[{"t":"64-bit dual-core processor and 4 GB RAM"}],[{"t":"Quad-core processor and 8 GB RAM"}]],[[{"t":"Free storage"}],[{"t":"5 GB"}],[{"t":"10 GB or more"}]],[[{"t":"Screen"}],[{"t":"1366 × 768 pixels"}],[{"t":"1920 × 1080 pixels, or an external monitor"}]],[[{"t":"Internet"}],[{"t":"5 Mbps download and 3 Mbps upload, stable"}],[{"t":"10 Mbps or more"}]],[[{"t":"Audio and video"}],[{"t":"Working microphone and headphones"}],[{"t":"Webcam, microphone and headphones"}]],[[{"t":"Power"}],[{"t":"A charger, and a plan for power cuts"}],[{"t":"A fully charged laptop and a phone hotspot as backup"}]]]},{"type":"paragraph","runs":[{"t":"The internet minimum leaves room for HD group video calls, which need about 1.5 Mbps each way at 720p and 2.5 Mbps down and 3.0 Mbps up at 1080p. Your LMS, uploads and a call will all share the same connection."}]},{"type":"heading","level":3,"text":"Tips for connectivity in India"},{"type":"list","ordered":false,"items":[[{"t":"Use broadband or campus Wi-Fi for uploads, online sessions and presentations."}],[{"t":"Keep a 4G or 5G phone hotspot with some data as a backup."}],[{"t":"Save your work often and keep a copy offline in case a power cut or a network drop interrupts you."}],[{"t":"Run a speed test before an online session or a deadline day, not during it."}]]},{"type":"heading","level":3,"text":"Tools you will use"},{"type":"table","header":[[{"t":"Tool"}],[{"t":"What it is for"}]],"rows":[[[{"t":"The LMS"}],[{"t":"Reading material, links, MCQs, assignment submission and your progress. Log in through your browser"}]],[[{"t":"A word processor (for example Google Docs or Word)"}],[{"t":"Writing your assignment documents"}]],[[{"t":"A presentation tool (for example Google Slides or PowerPoint)"}],[{"t":"Preparing your jury presentations"}]],[[{"t":"A spreadsheet tool (for example Google Sheets or Excel)"}],[{"t":"Organising research notes and data"}]],[[{"t":"The meeting tool your program team names"}],[{"t":"Online sessions and any online presentations"}]],[[{"t":"An AI assistant of your choice"}],[{"t":"Allowed uses only, as set out in the AI ground rules"}]],[[{"t":"An email address you check daily"}],[{"t":"Account access and program messages"}]]]},{"type":"heading","level":3,"text":"Setup checklist"},{"type":"checklist","persisted":false,"items":["I can log in to the LMS from my browser.","My browser and operating system are up to date.","My internet speed is at least 5 Mbps download and 3 Mbps upload.","My microphone and headphones work, and my webcam works if I have one.","I have a charger and a backup connection plan.","I can create and save documents, slides and spreadsheets."]}]'::jsonb,
   'I have read and understood the System requirements and tools section.', null, 'level-0/module-0-ground-rules-and-setup.docx', 'Product Wizardry_Module 0_Ground Rules & Setup.docx', 'b739d207425c5319e60e27d866a9a6187e8f7236f8b56b4f517ca817a4e618e4')
