-- Sanity check: the seed is complete and consistent.
do $$
begin
  if (select count(*) from public.course_subtopics where level_id = 1) <> 6
     or (select count(*) from public.quiz_questions where quiz_id = 'l0-plagiarism-quiz') <> 10
     or (select count(*) from private.quiz_answer_keys where quiz_id = 'l0-plagiarism-quiz' and explanation is not null) <> 10
     or exists (select 1 from public.quiz_questions q join private.quiz_answer_keys k using (quiz_id, question_id)
                 where q.quiz_id = 'l0-plagiarism-quiz' and jsonb_array_length(q.options) <> k.option_count) then
    raise exception 'Level 0 content seed is incomplete or inconsistent';
  end if;
end
$$;

commit;
